import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"ADR-0086: Bootstrap Formatter (plugin-ext-fmt)","description":"","frontmatter":{},"headers":[],"relativePath":"handl/project/adrs/0086-bootstrap-formatter.md","filePath":"vendored/handl/project/adrs/0086-bootstrap-formatter.md"}`),a={name:`handl/project/adrs/0086-bootstrap-formatter.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0086-bootstrap-formatter-plugin-ext-fmt" tabindex="-1">ADR-0086: Bootstrap Formatter (<code>plugin-ext-fmt</code>) <a class="header-anchor" href="#adr-0086-bootstrap-formatter-plugin-ext-fmt" aria-label="Permalink to “ADR-0086: Bootstrap Formatter (plugin-ext-fmt)”">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to “Status”">​</a></h2><p>Implemented (merged to main). Part of the bootstrap tooling strategy (<a href="./0085-bootstrap-tooling-strategy.html">ADR-0085</a>; refines the generic design in <a href="./../0014-formatter.html">ADR-0014</a> — which stays valid — into a concrete implementation). Temporary: will be replaced by the self-hosted formatter described in <a href="./../rfcs/0002-formatter-in-handl.html">RFC-0002</a>.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>The v0.1 arrow surface syntax (ADR-0074) is now being used to write the handl stdlib and examples. There is no formatter for it. The generic, plugin-driven formatter of ADR-0014 was never implemented and presumes a pre-arrow document model. We need a real formatter now, coupled to the one syntax that exists.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p><code>plugin-ext-fmt</code> is the canonical formatter: a Rust implementation, built on the generic format capability contracts, that formats <code>.handl</code> files written in the v0.1 surface syntax.</p><ul><li><strong>Input/output:</strong> surface source text → parse (via <code>plugin-engine-parse</code> over the <code>handl-language</code> AST) → canonical layout → source text. Formatting is AST-driven; comments and tokens are preserved via the token stream, not reflowed.</li><li><strong>Hardcoded style, no configuration.</strong> Canonical preferences: <ol><li>Two-space indentation; continuation lines align with enclosing arrows.</li><li>One statement per line inside graph blocks; a blank line between top-level declarations.</li><li>Single trailing newline; no trailing whitespace; no more than one consecutive blank line.</li><li><code>&gt;&gt;&gt;</code> chains break <em>before</em> the operator, one segment per line, when a chain does not fit in 100 columns.</li><li>No spaces inside brackets; single spaces around binary operators per the ADR-0074 precedence table.</li></ol></li><li><strong>Idempotence:</strong> <code>fmt(fmt(src)) == fmt(src)</code> — tested exhaustively.</li><li><strong>API surface (minimal):</strong><ul><li><code>format_source(src: &amp;str) -&gt; Result&lt;String, FormatError&gt;</code></li><li><code>check_source(src: &amp;str) -&gt; Result&lt;bool, FormatError&gt;</code> (true = already canonical)</li></ul></li><li><strong>CLI contract:</strong> <code>hnl fmt [--check] [--write] [paths...]</code>. <code>--check</code> exits 1 with a diff on stdout if any file is not canonical; <code>--write</code> rewrites files atomically. Globbing/paths are the caller&#39;s job.</li><li><strong>Testing:</strong> 100% coverage. Golden-file tests under <code>tests/golden/</code> (one input, one expected output per construct in ADR-0074), plus an idempotence property test over all goldens and the repo&#39;s own <code>.handl</code> examples.</li></ul><p>Explicitly out of scope: configuration files, formatting other dialects, comment reflow, plugin-contributed rules (all RFC-0002).</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>stdlib and example code get canonical formatting immediately; CI can gate with <code>hnl fmt --check</code>.</li><li>Style changes require editing Rust and bumping goldens — acceptable until RFC-0002.</li><li>The crate must track ADR-0074 grammar changes (<code>ARROW_GRAMMAR_V0_1.md</code>); parser changes are a hard dependency, so <code>plugin-ext-fmt</code> pins the workspace <code>plugin-engine-parse</code> version and CI fails loudly on drift. The formatter consumes and produces the shared diagnostics types from <code>plugin-ext-diag</code> (ADR-0091).</li></ul><h2 id="status-1" tabindex="-1">Status <a class="header-anchor" href="#status-1" aria-label="Permalink to “Status”">​</a></h2><p>Implemented (merged to main).</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};